def _load_env() -> None:
    """Load .env when python-dotenv is installed, without hard dependency."""
    if importlib.util.find_spec("dotenv") is None:
        return

    dotenv = importlib.import_module("dotenv")
    dotenv.load_dotenv(Path(__file__).resolve().parents[1] / ".env")


_load_env()

JIRA_URL = (os.getenv("JIRA_URL") or "").rstrip("/")
JIRA_EMAIL = os.getenv("JIRA_EMAIL")
JIRA_TOKEN = os.getenv("JIRA_TOKEN")

JIRA_PROJECTS_API = "/rest/api/3/project"
JIRA_ISSUE_SEARCH_API = "/rest/api/3/search/jql"
JIRA_ISSUE_DETAILS_API = "/rest/api/3/issue/{issue_key}"
ISSUE_FIELDS = "summary,issuetype,priority,status,assignee,project,affectsVersions,versions,fixVersions"
ISSUE_DETAIL_FIELDS = "summary,description,issuetype,priority,status,assignee,project"


# Generated by GitHub Copilot
def _jira_get(path: str, params: dict[str, Any] | None = None) -> dict[str, Any] | list[dict[str, Any]]:
    """Run a Jira GET call and return JSON payload, or an empty structure on failure."""
    if not JIRA_URL or not JIRA_EMAIL or not JIRA_TOKEN:
        return [] if path == JIRA_PROJECTS_API else {}

    try:
        response = requests.get(
            f"{JIRA_URL}{path}",
            auth=HTTPBasicAuth(JIRA_EMAIL, JIRA_TOKEN),
            headers={"Accept": "application/json"},
            params=params,
            timeout=20,
        )
    except requests.RequestException:
        return [] if path == JIRA_PROJECTS_API else {}

    if response.status_code != 200:
        return [] if path == JIRA_PROJECTS_API else {}

    try:
        return response.json()
    except ValueError:
        return [] if path == JIRA_PROJECTS_API else {}


