def get_stored_projects(db: Session) -> list[Project]:
    """Return locally stored projects that have a configured Jira key."""
    rows = (
        db.query(Project)
        .filter(Project.jira_project.isnot(None))
        .order_by(Project.project_name.asc())
        .all()
    )
    return [row for row in rows if not is_excluded_project_name(row.project_name)]


# Generated by GitHub Copilot
def sync_projects(db: Session) -> dict[str, int]:
    """Upsert Jira projects into local project records by jira_project key."""
    jira_projects = get_live_projects()

    inserted = 0
    updated = 0

    for jira_project in jira_projects:
        project_key = jira_project.get("key")
        project_name = jira_project.get("name")

        if not project_key:
            continue
        if is_excluded_project_name(project_name):
            continue

        project = db.query(Project).filter(Project.jira_project == project_key).first()
        if project:
            if project_name and project.project_name != project_name:
                project.project_name = project_name
                updated += 1
            continue

        db.add(
            Project(
                project_name=project_name or project_key,
                jira_project=project_key,
            )
        )
        inserted += 1

    db.commit()

    return {
        "total_from_jira": len(jira_projects),
        "inserted": inserted,
        "updated": updated,
    }


