def _search_issues(project_key: str, start_at: int = 0, max_results: int = 50) -> dict[str, Any]:
    """Fetch one Jira issue page for a given project key."""
    payload = _jira_get(
        JIRA_ISSUE_SEARCH_API,
        params={
            "jql": f"project={project_key} ORDER BY created DESC",
            "startAt": start_at,
            "maxResults": max_results,
            "fields": ISSUE_FIELDS,
        },
    )
    return payload if isinstance(payload, dict) else {}


