def create_or_get_release(
    db: Session,
    project_id: int,
    version: str | None,
    release_name: str | None = None,
) -> Release | None:
    """
    Create or get a Release for a given Project and Version.
    
    Logic:
    1. If version is None, use "UNVERSIONED"
    2. Query for existing (project_id, version) pair
    3. If exists: return it
    4. If not exists: create new Release with auto-generated release_id
    
    Returns:
    - Release object with populated release_id (auto-generated)
    - None if project doesn't exist
    """
    if not project_id:
        return None
    
    version_value = version or "UNVERSIONED"
    
    # Check if release already exists
    existing = (
        db.query(Release)
        .filter(
            Release.project_id == project_id,
            Release.version == version_value,
        )
        .first()
    )
    
    if existing:
        return existing
    
    # Get project to use its name as release name
    project = db.query(Project).filter(Project.project_id == project_id).first()
    if not project:
        return None
    
    # Create new release
    new_release = Release(
        project_id=project_id,
        release_name=release_name or project.project_name,
        version=version_value,
        status="In Progress",
    )
    db.add(new_release)
    db.flush()  # Ensures release_id is auto-generated
    
    return new_release


