def _resolve_release_id(db: Session, project_key: str, release_id: int | None) -> int | None:
    """Resolve the release id for issue sync using explicit id or latest release by Jira project."""
    if release_id is not None:
        release = db.query(Release).filter(Release.release_id == release_id).first()
        return release.release_id if release else None

    project = db.query(Project).filter(Project.jira_project == project_key).first()
    if not project:
        return None

    latest_release = (
        db.query(Release)
        .filter(Release.project_id == project.project_id)
        .order_by(Release.release_id.desc())
        .first()
    )
    return latest_release.release_id if latest_release else None


